import java.util.*;
public class PIEFLAVORED{
   private static final long mod = 998244353;
   public static void main(String[] args) {
      Scanner ray = new Scanner(System.in);
      int n = ray.nextInt();
      long kk = ray.nextLong();
      if(kk >= n) {
         System.out.println("0");
      } else {
         int k = (int)kk;
         int r = n - k;
         long[] rChoose = new long[r+1];
         rChoose[0] = 1L;
         for(int i=1; i<=r; i++) {
            long inv = power(i, mod-2);
            rChoose[i] = rChoose[i-1] * (r - i + 1) % mod * inv % mod;
         }
         long ans = 0;
         long sign = 1;
         for(int i=0; i<=r; i++) {
            ans = (ans + power((long)(r-i), (long)n) * sign % mod * rChoose[i]) % mod;
            sign = -sign;
         }
         ans = ans * choose((long)n, (long)k) % mod;
         if(k > 0) ans = (ans * 2) % mod;
         if(ans < 0) ans += mod;
         System.out.println(""+ans);
      }
   }
   public static long choose(long n, long k) {
      long num = 1, den = 1;
      for(int i=(int)(n-k+1); i<=n; i++) num = (num * i) % mod;
      for(int i=1; i<=k; i++) den = (den * i) % mod;
      den = power(den, mod-2);
      return (num * den) % mod;
   }
   public static long power(long x, long y) {
      long res = 1;
      x %= mod;
      while (y > 0) {
         if ((y & 1) == 1) { res = (res * x) % mod; }
         y >>= 1;
         x = (x * x) % mod;
      }
      return res;
   }
}
